import sys

# 求解功能写在外部函数里
def solve():
    input = sys.stdin.readline
    T = int(input())
    LOG = 20  # 因为 n <= 2e5，2^18 > 2e5，开到 20 足够

    for _ in range(T):
        n, q = map(int, input().split())
        g = [[] for _ in range(n + 1)]

        # 建树
        for _ in range(n - 1):
            x, y = map(int, input().split())
            g[x].append(y)
            g[y].append(x)

        # 倍增祖先表和深度
        up = [[0] * (n + 1) for _ in range(LOG)]
        depth = [0] * (n + 1)

        # 用栈模拟 DFS，避免递归过深
        stack = [1]
        parent = [0] * (n + 1)
        parent[1] = 0
        order = []

        while stack:
            u = stack.pop()
            order.append(u)
            for v in g[u]:
                if v == parent[u]:
                    continue
                parent[v] = u
                depth[v] = depth[u] + 1
                stack.append(v)

        # 初始化第 0 层祖先
        for i in range(1, n + 1):
            up[0][i] = parent[i]

        # 倍增预处理
        for k in range(1, LOG):
            for i in range(1, n + 1):
                up[k][i] = up[k - 1][up[k - 1][i]]

        # 普通 LCA
        def lca(u, v):
            if depth[u] < depth[v]:
                u, v = v, u

            # 先把 u 跳到和 v 同一深度
            diff = depth[u] - depth[v]
            for k in range(LOG):
                if diff >> k & 1:
                    u = up[k][u]

            if u == v:
                return u

            # 一起向上跳
            for k in range(LOG - 1, -1, -1):
                if up[k][u] != up[k][v]:
                    u = up[k][u]
                    v = up[k][v]

            return up[0][u]

        ans = []
        for _ in range(q):
            r, u, v = map(int, input().split())

            a = lca(u, v)
            b = lca(u, r)
            c = lca(v, r)

            # 按结论分类讨论
            if a == b:
                ans.append(str(c))
            elif a == c:
                ans.append(str(b))
            else:
                ans.append(str(a))

        sys.stdout.write("\n".join(ans) + "\n")


# 输入输出写在主函数里
if __name__ == "__main__":
    solve()
```

